B.WV=new A.l7("rules_version = '2';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n    // ===== Chronopost =====\n    function logueado() { return request.auth != null; }\n    function cfg() { return /databases/$(database)/documents/config/equipo; }\n    function hayAdmin() { return exists(cfg()); }\n    function esAdmin() { return hayAdmin() && request.auth.uid in get(cfg()).data.admins; }\n    function yo() { return get(/databases/$(database)/documents/usuarios/$(request.auth.uid)).data; }\n    function accesoTotal() { return !hayAdmin() || esAdmin() || ('marcas' in yo() && '*' in yo().marcas); }\n    function puedeMarca(m) { return accesoTotal() || ('marcas' in yo() && m in yo().marcas); }\n\n    match /config/equipo {\n      allow read: if logueado();\n      // El primero que lo pide queda como administrador; luego solo un admin lo cambia.\n      allow create: if logueado() && request.resource.data.admins == [request.auth.uid];\n      allow update: if esAdmin() && request.resource.data.admins.size() > 0;\n    }\n    match /usuarios/{uid} {\n      allow read: if logueado();\n      allow create: if logueado() && request.auth.uid == uid && !('marcas' in request.resource.data);\n      allow update: if esAdmin() || (logueado() && request.auth.uid == uid\n                    && !request.resource.data.diff(resource.data).affectedKeys().hasAny(['marcas']));\n      allow delete: if esAdmin();\n    }\n    match /marcas/{id} {\n      allow read: if logueado();\n      allow write: if logueado() && accesoTotal();\n    }\n    match /publicaciones/{id} {\n      allow read: if logueado() && puedeMarca(resource.data.cliente);\n      allow create: if logueado() && puedeMarca(request.resource.data.cliente);\n      allow update: if logueado() && puedeMarca(resource.data.cliente) && puedeMarca(request.resource.data.cliente);\n      allow delete: if logueado() && puedeMarca(resource.data.cliente);\n    }\n  }\n}")
